package com.portfolio.cms.controller;
import com.portfolio.cms.entity.Media; import com.portfolio.cms.repository.MediaRepository; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.util.StringUtils; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/upload") @RequiredArgsConstructor
public class UploadController {
 private final MediaRepository repo; @Value("${app.media-dir}") String mediaDir; @Value("${app.public-base-url}") String baseUrl;
 @PostMapping("/image") public ResponseEntity<Media> upload(@RequestParam("file") MultipartFile file)throws IOException{if(file.isEmpty())throw new IllegalArgumentException("File is empty"); if(file.getContentType()==null||!file.getContentType().startsWith("image/"))throw new IllegalArgumentException("Only image files are allowed"); Path dir=Paths.get(mediaDir);Files.createDirectories(dir);String ext=StringUtils.getFilenameExtension(file.getOriginalFilename());String stored=UUID.randomUUID()+ (ext==null?"":"."+ext.toLowerCase());Files.copy(file.getInputStream(),dir.resolve(stored),StandardCopyOption.REPLACE_EXISTING);Media m=new Media();m.setOriginalName(file.getOriginalFilename());m.setStoredName(stored);m.setContentType(file.getContentType());m.setSize(file.getSize());m.setUrl(baseUrl+"/media/"+stored);return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(m));}
}
